struct ParsedControl {std::string kind="OTHER",ipSrc,ipDst,origin,dst,unreachable;int ipId=-1,ipProto=-1,ttl=-1,id=-1,hop=-1,originSeq=-1,dstSeq=-1,ack=-1,gratuitous=-1,dstOnly=-1,flow=-1,seq=-1;double lifetime=-1;};
std::string IpString(Ipv4Address ip){std::ostringstream os;os<<ip;return os.str();}
ParsedControl ParseControl(Ptr<Packet>p,bool llc){ParsedControl c;if(llc){if(p->GetSize()<8)return c;LlcSnapHeader h;p->RemoveHeader(h);if(h.GetType()==0x0806){c.kind="ARP";return c;}if(h.GetType()!=0x0800)return c;}if(p->GetSize()<20)return c;Ipv4Header ip;if(p->RemoveHeader(ip)==0)return c;c.ipId=ip.GetIdentification();c.ipProto=ip.GetProtocol();c.ipSrc=IpString(ip.GetSource());c.ipDst=IpString(ip.GetDestination());c.ttl=ip.GetTtl();if(ip.GetProtocol()!=17||p->GetSize()<8)return c;UdpHeader udp;p->RemoveHeader(udp);if(udp.GetDestinationPort()>=5000&&udp.GetDestinationPort()<5000+flows.size()){c.kind="DATA";c.flow=udp.GetDestinationPort()-5000;if(p->GetSize()>=12){SeqTsHeader h;p->RemoveHeader(h);c.seq=h.GetSeq();}return c;}if(udp.GetDestinationPort()!=654||p->GetSize()<1)return c;aodv::TypeHeader type;p->RemoveHeader(type);if(!type.IsValid()){c.kind="INVALID_AODV";return c;}
 if(type.Get()==aodv::AODVTYPE_RREQ){aodv::RreqHeader h;p->RemoveHeader(h);c.kind="RREQ";c.origin=IpString(h.GetOrigin());c.dst=IpString(h.GetDst());c.id=h.GetId();c.hop=h.GetHopCount();c.originSeq=h.GetOriginSeqno();c.dstSeq=h.GetDstSeqno();c.gratuitous=h.GetGratuitousRrep();c.dstOnly=h.GetDestinationOnly();}
 else if(type.Get()==aodv::AODVTYPE_RREP){aodv::RrepHeader h;p->RemoveHeader(h);c.kind=(h.GetOrigin()==h.GetDst()&&h.GetDst()==ip.GetSource()&&h.GetHopCount()==0)?"HELLO":"RREP";c.origin=IpString(h.GetOrigin());c.dst=IpString(h.GetDst());c.hop=h.GetHopCount();c.dstSeq=h.GetDstSeqno();c.ack=h.GetAckRequired();c.lifetime=h.GetLifeTime().GetSeconds();}
 else if(type.Get()==aodv::AODVTYPE_RERR){aodv::RerrHeader h;p->RemoveHeader(h);c.kind="RERR";std::pair<Ipv4Address,uint32_t>un;while(h.RemoveUnDestination(un))c.unreachable+=IpString(un.first)+":"+std::to_string(un.second)+";";}
 else if(type.Get()==aodv::AODVTYPE_RREP_ACK)c.kind="RREP_ACK";
 return c;}
void ControlTrace(uint32_t node,std::string event,Ptr<const Packet>packet,Ptr<Ipv4>ip,uint32_t interface){auto c=ParseControl(packet->Copy(),false);if(c.kind=="OTHER")return;controlEvents<<std::setprecision(12)<<Simulator::Now().GetSeconds()<<","<<observationOrder++<<","<<node<<","<<event<<","<<interface<<","<<packet->GetUid()<<","<<packet->GetSize()<<","<<c.kind<<","<<c.ipSrc<<","<<c.ipDst<<","<<c.ttl<<","<<c.origin<<","<<c.dst<<","<<c.id<<","<<c.hop<<","<<c.originSeq<<","<<c.dstSeq<<","<<c.ack<<","<<c.lifetime<<","<<c.gratuitous<<","<<c.dstOnly<<","<<c.flow<<","<<c.seq<<","<<c.unreachable<<","<<c.ipId<<","<<c.ipProto<<"\n";}
void AirTrace(uint32_t node,WifiConstPsduMap map,WifiTxVector vector,double power){NS_ABORT_MSG_IF(map.size()!=1,"unexpected MU PPDU");auto psdu=map.begin()->second;NS_ABORT_MSG_IF(std::distance(psdu->begin(),psdu->end())!=1,"unexpected aggregate");auto mpdu=*psdu->begin();const auto &mac=mpdu->GetHeader();ParsedControl c;if(mac.IsData())c=ParseControl(mpdu->GetPacket()->Copy(),true);else c.kind=mac.IsAck()?"MAC_ACK":"OTHER_MAC";Time duration=WifiPhy::CalculateTxDuration(map,vector,WIFI_PHY_BAND_2_4GHZ);airtimeEvents<<std::setprecision(12)<<Simulator::Now().GetSeconds()<<","<<node<<","<<duration.GetNanoSeconds()<<","<<psdu->GetSize()<<","<<c.kind<<","<<mac.GetAddr1()<<","<<mac.GetAddr1().IsGroup()<<","<<mac.IsRetry()<<","<<c.origin<<","<<c.dst<<","<<c.id<<","<<c.hop<<","<<c.dstSeq<<","<<c.flow<<","<<c.seq<<"\n";}
void SetupControlObservation(const NetDeviceContainer&devices){controlEvents.open(output+"-control-events.csv");airtimeEvents.open(output+"-airtime.csv");controlEvents<<"time,order,node,event,interface,packet_uid,ip_bytes,kind,ip_source,ip_destination,ttl,origin,destination,request_id,hop,origin_seq,destination_seq,ack_required,lifetime,gratuitous,destination_only,flow,seq,unreachable,ip_id,ip_protocol\n";airtimeEvents<<"time,node,duration_ns,psdu_bytes,kind,receiver_mac,group,retry,origin,destination,request_id,hop,destination_seq,flow,seq\n";NS_ABORT_MSG_IF(!controlEvents.good()||!airtimeEvents.good(),"observer output failed");for(uint32_t i=0;i<nodes.GetN();i++){auto ip=nodes.Get(i)->GetObject<Ipv4L3Protocol>();NS_ABORT_MSG_IF(!ip->TraceConnectWithoutContext("Tx",MakeBoundCallback(&ControlTrace,i,std::string("TX"))),"control TX trace failed");NS_ABORT_MSG_IF(!ip->TraceConnectWithoutContext("Rx",MakeBoundCallback(&ControlTrace,i,std::string("RX"))),"control RX trace failed");auto wifi=DynamicCast<WifiNetDevice>(devices.Get(i));NS_ABORT_MSG_IF(!wifi->GetPhy()->TraceConnectWithoutContext("PhyTxPsduBegin",MakeBoundCallback(&AirTrace,i)),"air trace failed");}}

struct Counter {uint64_t bytes=0,frames=0,retries=0,controlBytes=0,dsrDataHeaderBytes=0,arpBytes=0,dataBytes=0,otherBytes=0,rxDrops=0;};std::map<std::pair<uint32_t,int>,Counter> counts;
std::map<std::tuple<uint32_t,int,std::string,int>,uint64_t> drops;
void TxTrace(uint32_t node,Ptr<const Packet> packet,double power){auto &c=counts[{node,int(Simulator::Now().GetSeconds())}];c.bytes+=packet->GetSize();c.frames++;auto p=packet->Copy();WifiMacHeader mac;if(p->PeekHeader(mac)==0){c.otherBytes+=packet->GetSize();return;}p->RemoveHeader(mac);if(mac.IsRetry())c.retries++;
 if(!mac.IsData()){c.otherBytes+=packet->GetSize();return;} LlcSnapHeader llc;if(p->GetSize()<8){c.otherBytes+=packet->GetSize();return;}p->RemoveHeader(llc);if(llc.GetType()==0x0806){c.arpBytes+=packet->GetSize();return;}if(llc.GetType()!=0x0800){c.otherBytes+=packet->GetSize();return;}Ipv4Header ip;p->RemoveHeader(ip);
 if(ip.GetProtocol()==17){UdpHeader u;p->PeekHeader(u);auto port=u.GetDestinationPort();if(port==654||port==698||port==269)c.controlBytes+=packet->GetSize();else c.dataBytes+=packet->GetSize();}
 else if(ip.GetProtocol()==48){dsr::DsrRoutingHeader h;p->PeekHeader(h);if(h.GetMessageType()==1)c.controlBytes+=packet->GetSize();else {c.dataBytes+=packet->GetSize();c.dsrDataHeaderBytes+=h.GetSerializedSize();}}
 else c.otherBytes+=packet->GetSize();}
void RxDrop(uint32_t node,Ptr<const Packet> p,WifiPhyRxfailureReason reason){counts[{node,int(Simulator::Now().GetSeconds())}].rxDrops++;drops[{node,int(Simulator::Now().GetSeconds()),"phy_rx",int(reason)}]++;}
void PacketIdentity(Ptr<Packet> p,bool llcPresent,int& flow,int& seq,std::string& src,std::string& dst){
 flow=-1;seq=-1;src="";dst="";if(llcPresent){if(p->GetSize()<8)return;LlcSnapHeader llc;p->RemoveHeader(llc);if(llc.GetType()!=0x0800)return;}if(p->GetSize()<20)return;Ipv4Header ip;if(p->RemoveHeader(ip)==0)return;std::ostringstream a,b;a<<ip.GetSource();b<<ip.GetDestination();src=a.str();dst=b.str();uint8_t proto=ip.GetProtocol();if(proto==48){dsr::DsrRoutingHeader d;p->RemoveHeader(d);proto=d.GetNextHeader();}if(proto!=17||p->GetSize()<8)return;UdpHeader udp;p->RemoveHeader(udp);if(udp.GetDestinationPort()<5000||udp.GetDestinationPort()>=5000+flows.size())return;flow=udp.GetDestinationPort()-5000;if(p->GetSize()<12)return;SeqTsHeader h;p->PeekHeader(h);seq=h.GetSeq();}
void FinalDrop(uint32_t node,WifiMacDropReason reason,Ptr<const WifiMpdu> mpdu){int f,q;std::string src,dst;PacketIdentity(mpdu->GetPacket()->Copy(),true,f,q,src,dst);macFinal<<std::setprecision(12)<<Simulator::Now().GetSeconds()<<","<<node<<","<<int(reason)<<","<<mpdu->GetHeader().GetAddr1()<<","<<f<<","<<q<<","<<src<<","<<dst<<","<<mpdu->GetPacket()->GetSize()<<"\n";}
void SampleArp(){double now=Simulator::Now().GetSeconds();for(uint32_t i=0;i<nodes.GetN();i++){auto cache=nodes.Get(i)->GetObject<Ipv4L3Protocol>()->GetInterface(1)->GetArpCache();for(uint32_t j=0;j<nodes.GetN();j++){if(i==j)continue;auto e=cache->Lookup(addresses.GetAddress(j));std::string state=!e?"ABSENT":e->IsDead()?"DEAD":e->IsAlive()?"ALIVE":e->IsWaitReply()?"WAIT_REPLY":"OTHER";bool expired=e&&e->IsExpired();double distance=CalculateDistance(nodes.Get(i)->GetObject<MobilityModel>()->GetPosition(),nodes.Get(j)->GetObject<MobilityModel>()->GetPosition());bool neighbor=distance<=rangeM;std::string code=state+":"+std::to_string(expired)+":"+std::to_string(neighbor);auto key=std::make_pair(i,j);if(oldArpState[key]!=code){if(e||oldArpState[key]!="")arpState<<std::setprecision(12)<<now<<","<<i<<","<<j<<","<<addresses.GetAddress(j)<<","<<state<<","<<expired<<","<<neighbor<<","<<distance<<"\n";oldArpState[key]=code;}}
 if(protocol=="OLSR"){auto routes=nodes.Get(i)->GetObject<olsr::RoutingProtocol>()->GetRoutingTableEntries();for(uint32_t f=0;f<flows.size();f++){auto dst=addresses.GetAddress(flows[f].dst);std::ostringstream value;value<<"NO_ROUTE";for(auto &r:routes)if(r.destAddr==dst){value.str("");value<<r.nextAddr<<","<<r.distance;break;}auto key=std::make_pair(i,f);if(oldRoute[key]!=value.str()){olsrRoutes<<std::setprecision(12)<<now<<","<<i<<","<<f<<","<<dst<<","<<value.str()<<"\n";oldRoute[key]=value.str();}}}}
 if(now+.5<=simStop)Simulator::Schedule(Seconds(.5),&SampleArp);}
void SimpleDrop(uint32_t node,std::string layer,Ptr<const Packet> p){drops[{node,int(Simulator::Now().GetSeconds()),layer,0}]++;if(diagnostic&&layer=="arp_pending_queue"){int f,q;std::string src,dst;PacketIdentity(p->Copy(),false,f,q,src,dst);arpDrops<<std::setprecision(12)<<Simulator::Now().GetSeconds()<<","<<node<<","<<f<<","<<q<<","<<src<<","<<dst<<"\n";}}
void QueueDrop(uint32_t node,std::string layer,Ptr<const WifiMpdu> p){drops[{node,int(Simulator::Now().GetSeconds()),layer,0}]++;}
void IpDrop(uint32_t node,const Ipv4Header& h,Ptr<const Packet> p,Ipv4L3Protocol::DropReason reason,Ptr<Ipv4> ip,uint32_t interface){drops[{node,int(Simulator::Now().GetSeconds()),"ipv4",int(reason)}]++;}
std::vector<std::vector<uint32_t>> Adjacency(){std::vector<std::vector<uint32_t>> a(nodes.GetN());for(uint32_t i=0;i<nodes.GetN();i++)for(uint32_t j=i+1;j<nodes.GetN();j++){auto x=nodes.Get(i)->GetObject<MobilityModel>()->GetPosition();auto y=nodes.Get(j)->GetObject<MobilityModel>()->GetPosition();if(CalculateDistance(x,y)<=rangeM){a[i].push_back(j);a[j].push_back(i);}}return a;}
int Hops(uint32_t s,uint32_t d,const std::vector<std::vector<uint32_t>>&a){std::vector<int>dist(a.size(),-1);dist[s]=0;std::queue<uint32_t>q;q.push(s);while(!q.empty()){auto u=q.front();q.pop();if(u==d)return dist[u];for(auto v:a[u])if(dist[v]<0){dist[v]=dist[u]+1;q.push(v);}}return -1;}
void SampleGraph(){auto a=Adjacency();double now=Simulator::Now().GetSeconds();for(uint32_t i=0;i<flows.size();i++)graph<<std::setprecision(12)<<now<<","<<i<<","<<Hops(flows[i].src,flows[i].dst,a)<<"\n";if(now+.5<=simStop)Simulator::Schedule(Seconds(.5),&SampleGraph);}
void Receive(uint32_t id,Ptr<Socket>s){Address from;while(auto p=s->RecvFrom(from)){uint32_t bytes=p->GetSize();SeqTsHeader h;if(bytes<h.GetSerializedSize())continue;p->RemoveHeader(h);auto &f=flows[id];uint32_t seq=h.GetSeq();double now=Simulator::Now().GetSeconds(),delay=(Simulator::Now()-h.GetTs()).GetSeconds();bool unique=f.seen.insert(seq).second;if(unique){f.received++;f.delays.push_back(delay);f.rxTimes.push_back(now);}else f.duplicates++;events<<std::setprecision(12)<<now<<","<<id<<",rx,"<<seq<<","<<bytes<<","<<delay<<","<<unique<<",\n";}}
void Send(uint32_t id){auto &f=flows[id];double now=Simulator::Now().GetSeconds();if(id==1 && mainPackets>0 && f.next>=mainPackets)return;if(now>=(id==0?9:mainAt+trafficDuration))return;uint32_t seq=f.next++;SeqTsHeader h;h.SetSeq(seq);Ptr<Packet>p=Create<Packet>(packetBytes-h.GetSerializedSize());p->AddHeader(h);f.planned++;int result=f.tx->Send(p);if(result==int(packetBytes)){f.sent++;f.accepted[seq]=now;}else f.sendErrors++;int hops=Hops(f.src,f.dst,Adjacency());events<<std::setprecision(12)<<now<<","<<id<<",tx,"<<seq<<","<<result<<",,"<<(result==int(packetBytes))<<","<<hops<<"\n";Simulator::Schedule(Seconds(packetInterval),&Send,id);}
void InjectRequest(){auto p=Create<Packet>();aodv::RreqHeader h;h.SetId(9001);h.SetDst(addresses.GetAddress(3));h.SetDstSeqno(0);h.SetUnknownSeqno(false);h.SetOrigin(addresses.GetAddress(0));h.SetOriginSeqno(100);h.SetHopCount(0);h.SetDestinationOnly(false);h.SetGratuitousRrep(false);p->AddHeader(h);p->AddHeader(aodv::TypeHeader(aodv::AODVTYPE_RREQ));UdpHeader udp;udp.SetSourcePort(654);udp.SetDestinationPort(654);p->AddHeader(udp);SocketIpTtlTag ttl;ttl.SetTtl(5);p->AddPacketTag(ttl);auto route=Create<Ipv4Route>();route->SetSource(addresses.GetAddress(0));route->SetDestination(Ipv4Address("10.1.1.255"));route->SetGateway(Ipv4Address::GetZero());route->SetOutputDevice(nodes.Get(0)->GetDevice(0));nodes.Get(0)->GetObject<Ipv4L3Protocol>()->Send(p,addresses.GetAddress(0),Ipv4Address("10.1.1.255"),17,route);}

