void SnapshotAll(){probePending=false;double now=Simulator::Now().GetSeconds();++snapshotId;
 for(uint32_t n=0;n<observedProtocols.size();n++){auto &tab=aodv::DiagnosticAccess::Table(observedProtocols[n]);auto it=tab.find(addresses.GetAddress(3));routeSnapshots<<std::setprecision(15)<<now<<","<<snapshotId<<","<<n<<","<<(it!=tab.end());if(it!=tab.end()){auto &e=it->second;routeSnapshots<<","<<int(e.GetFlag())<<","<<e.GetValidSeqNo()<<","<<e.GetSeqNo()<<","<<e.GetNextHop()<<","<<e.GetHop()<<","<<(now+e.GetLifeTime().GetSeconds());}else routeSnapshots<<",,,,,,";routeSnapshots<<"\n";}
}
void RequestSnapshot(){SnapshotAll();}
void PositivePerturb(){auto dst=addresses.GetAddress(3);bool pass=true;uint32_t seq=0;
 for(uint32_t n:{0u,1u}){auto &t=aodv::DiagnosticAccess::Table(observedProtocols[n]);auto it=t.find(dst);bool ok=it!=t.end();if(ok){auto&e=it->second;ok=e.GetFlag()==aodv::VALID&&e.GetValidSeqNo()&&e.GetLifeTime().IsStrictlyPositive()&&e.GetNextHop()==(n==0?dst:addresses.GetAddress(0));if(n==0)seq=e.GetSeqNo();else ok=ok&&seq==e.GetSeqNo();}pass=pass&&ok;qualifications<<"before,"<<n<<","<<ok<<"\n";}
 SnapshotAll();if(pass){aodv::DiagnosticAccess::InvalidateOnly(observedProtocols[0],dst);qualifications<<"perturb,0,1\n";}else qualifications<<"perturb,0,0\n";SnapshotAll();
}
