t("ns3::ArpCache::DeadTimeout",TimeValue(Seconds(arpDeadTimeout)));
 NS_ABORT_MSG_IF(protocol!="AODV"&&protocol!="OLSR"&&protocol!="DSDV"&&protocol!="DSR"&&protocol!="STATIC","unknown protocol");RngSeedManager::SetSeed(20261030);RngSeedManager::SetRun(runId);Time::SetResolution(Time::NS);if(qualification){appStart=30;appStop=130;simStop=160;}
